round: rgb(164, 83, 45); }.cols { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }.newsletter { display: flex; justify-content: space-between; align-items: center; gap: 32px; padding-bottom: 56px; }.newsletter p { margin: 0px; }input, select { font: inherit; padding: 11px 12px; border: 1px solid rgb(207, 198, 187); border-radius: 6px; background: rgb(255, 255, 255); color: var(--ink); width: 100%; }input:focus, select:focus { outline: 2px solid var(--accent); outline-offset: -1px; }.newsletter input { width: 280px; }.foot { border-top: 1px solid var(--line); background: var(--surface); margin-top: 48px; }.foot-inner { display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 32px; padding-top: 36px; padding-bottom: 44px; font-size: 14px; }.foot-inner > div { display: flex; flex-direction: column; gap: 6px; }.foot .logo { font-size: 18px; }.product { display: grid; grid-template-columns: 1fr 1fr; gap: 56px; align-items: start; }.price.big { font-size: 24px; font-weight: 600; margin-bottom: 4px; }.rating { font-size: 14px; color: var(--muted); margin-bottom: 16px; }.stars { color: rgb(183, 121, 31); letter-spacing: 1px; }.field { display: flex; flex-direction: column; gap: 6px; margin: 16px 0px; border: 0px; padding: 0px; }.field > span, .field legend { font-size: 14px; font-weight: 600; padding: 0px; margin-bottom: 6px; }.seg { display: flex; gap: 8px; }.seg label { flex: 1 1 0%; }.seg input { position: absolute; opacity: 0; width: 0px; }.seg span { display: block; text-align: center; border: 1px solid rgb(207, 198, 187); border-radius: 6px; padding: 10px; background: rgb(255, 255, 255); cursor: pointer; }.seg input:checked + span { border-color: var(--ink); box-shadow: inset 0 0 0 1px var(--ink); font-weight: 600; }.stepper { display: flex; align-items: center; border: 1px solid rgb(207, 198, 187); border-radius: 6px; background: rgb(255, 255, 255); }.stepper button { border: 0px; background: none; font-size: 18px; width: 40px; height: 44px; cursor: pointer; color: var(--ink); }.stepper span { min-width: 24px; text-align: center; font-weight: 600; }.stepper.small { width: max-content; margin-top: 6px; }.stepper.small button { height: 30px; width: 30px; font-size: 15px; }.toast { display: none; margin-top: 14px; border-left: 3px solid rgb(47, 107, 69); background: rgb(238, 245, 240); padding: 10px 14px; font-size: 15px; }.toast.show { display: block; }.toast a { font-weight: 600; text-decoration: underline; }.details { width: 100%; border-collapse: collapse; margin-top: 28px; font-size: 15px; }.details th, .details td { text-align: left; padding: 10px 0px; border-top: 1px solid var(--line); vertical-align: top; }.details th { font-weight: 600; width: 40%; }.reviews { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }.review p { font-size: 15px; }.two-col { display: grid; grid-template-columns: 1.5fr 1fr; gap: 48px; align-items: start; }.summary { background: var(--surface); border: 1px solid var(--line); border-radius: 6px; padding: 24px; }.summary h2 { font-size: 22px; }.line { display: flex; gap: 16px; align-items: center; padding: 16px 0px; border-bottom: 1px solid var(--line); }.thumb { width: 64px; height: 64px; border-radius: 4px; flex: 0 0 auto; }.line-main { display: flex; flex-direction: column; flex: 1 1 0%; font-size: 14px; }.line-main strong { font-size: 16px; }.line-price { display: flex; flex-direction: column; align-items: flex-end; gap: 6px; font-weight: 600; }.sum-row { display: flex; justify-content: space-between; padding: 6px 0px; font-size: 15px; }.sum-row.total { font-weight: 700; font-size: 18px; border-top: 1px solid var(--line); margin-top: 8px; padding-top: 14px; margin-bottom: 16px; }.form h2 { font-size: 22px; margin-top: 32px; }.form h2:first-child { margin-top: 0px; }.option { display: flex; gap: 12px; align-items: center; border: 1px solid rgb(207, 198, 187); border-radius: 6px; padding: 12px 14px; margin: 8px 0px; cursor: pointer; background: rgb(255, 255, 255); }.option input { width: auto; accent-color: var(--ink); }.option > span:nth-child(2) { display: flex; flex-direction: column; flex: 1 1 0%; font-size: 14px; }.option > span:nth-child(2) strong { font-size: 15px; }.option:has(input:checked) { border-color: var(--ink); box-shadow: inset 0 0 0 1px var(--ink); }.form .btn.wide { margin-top: 20px; padding: 14px; }.confirm { max-width: 720px; padding-top: 72px; padding-bottom: 48px; }@media (max-width: 820px) {
  h1 { font-size: 32px; }
  h2 { font-size: 22px; }
  .wrap { padding-left: 16px; padding-right: 16px; }
  .section { padding-top: 32px; }
  .nav { display: none; }
  .hero, .product, .two-col { grid-template-columns: 1fr; gap: 24px; }
  .hero { padding-top: 28px; padding-bottom: 28px; }
  .grid, .grid.three { grid-template-columns: repeat(2, 1fr); gap: 16px; }
  .cols, .reviews { grid-template-columns: 1fr; gap: 20px; }
  .newsletter { flex-direction: column; align-items: stretch; }
  .newsletter input { width: 100%; }
  .foot-inner { grid-template-columns: 1fr; }
